// ---------------------------------------------------------------
// Configure domains and brands here. 5 domains × 6 brands = 30 queries.
// Queries are generated in the form: site:<brand>.<domain>
// ---------------------------------------------------------------
const domains = [
  'site1.example.com',
  'site2.example.com',
  'site3.example.com',
  'site4.example.com',
  'site5.example.com'
];

const brands = [
  'aurora',
  'cryptoboss',
  'eva',
  'enomo',
  'avocado',
  'bonsai'
];

// ---------------------------------------------------------------
// Google Sheet layout (matches the reference screenshot):
//   Row 1: merged title
//   Row 2: site headers (Сайт 1, Сайт 2, ...)
//   Row 3: sub-headers (Индексация, Топ3, Топ5, Топ10, Топ20, Топ50)
//   Rows 4..9: brand rows (Aurora, Cryptoboss, Eva, Enomo, Avocado, Bonsai)
// Each site occupies 6 columns. The first column of each group is
// "Индексация" — the only column this workflow writes to.
// ---------------------------------------------------------------
const SHEET_NAME = $env.GOOGLE_SHEET_TAB || 'Мониторинг';
const FIRST_BRAND_ROW = 4;
const INDEXING_COLUMNS = ['B', 'H', 'N', 'T', 'Z']; // site 1..5

if (domains.length !== INDEXING_COLUMNS.length) {
  throw new Error(`Domains count (${domains.length}) must match indexing columns count (${INDEXING_COLUMNS.length}).`);
}

const items = [];
for (let b = 0; b < brands.length; b++) {
  for (let s = 0; s < domains.length; s++) {
    const brand = brands[b];
    const domain = domains[s];
    const row = FIRST_BRAND_ROW + b;
    const column = INDEXING_COLUMNS[s];
    items.push({
      json: {
        brand,
        domain,
        query: `site:${brand}.${domain}`,
        sheetName: SHEET_NAME,
        row,
        column,
        cell: `${column}${row}`,
        a1Range: `${SHEET_NAME}!${column}${row}`
      }
    });
  }
}

return items;

// Extract total indexed-pages count from parsed XMLStock response.
// XMLStock returns several <found priority="..."> tags. We prefer
// priority="phrase" (the value the web UI shows for site: queries),
// then fall back to "all" and "strict".

const xmlItem = $input.first();
const parsed = xmlItem.json?.data ?? xmlItem.json ?? {};
const meta = $('Loop Over Queries').first().json;

function pickFound(response) {
  if (!response) return null;
  const foundRaw = response.found;
  if (foundRaw == null) return null;

  const arr = Array.isArray(foundRaw) ? foundRaw : [foundRaw];
  const byPriority = (p) => arr.find((f) => {
    const attr = f?.$?.priority ?? f?._attributes?.priority ?? f?.priority;
    return attr === p;
  });

  const candidate = byPriority('phrase') || byPriority('all') || byPriority('strict') || arr[0];
  if (candidate == null) return null;

  // xml2js / n8n XML node variants: value can be under `_`, `#`, or be a primitive.
  const raw = candidate._ ?? candidate['#'] ?? candidate['#text'] ?? (typeof candidate === 'object' ? null : candidate);
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

const response = parsed?.yandexsearch?.response ?? parsed?.response ?? null;
const errorNode = response?.error ?? parsed?.yandexsearch?.error;
const errorText = errorNode ? (errorNode._ ?? errorNode['#'] ?? errorNode['#text'] ?? String(errorNode)) : null;

const found = pickFound(response);

return [
  {
    json: {
      brand: meta.brand,
      domain: meta.domain,
      query: meta.query,
      sheetName: meta.sheetName,
      row: meta.row,
      column: meta.column,
      cell: meta.cell,
      a1Range: meta.a1Range,
      found: found,
      value: found == null ? 'ERR' : found,
      error: errorText,
      timestamp: new Date().toISOString()
    }
  }
];
